package app.velora.reader.crtui;
/** Edge-local blur with preserved source alpha; the centre is sampled once. */
final class ScrollEdgeBlurShader { static final String SOURCE="uniform shader content;\nuniform float2 size;\nuniform float density;\nuniform float2 edges;\nhalf4 main(float2 p){\n float2 lo=float2(0.5),hi=max(lo,size-lo),q=clamp(p,lo,hi);\n float band=min(22.0*density,size.y*0.12);\n float a=max((1.0-smoothstep(0.0,band,p.y))*edges.x,(1.0-smoothstep(0.0,band,size.y-p.y))*edges.y);\n half4 c=content.eval(q);\n if(a<0.001)return c;\n float r=5.0*density*a;\n half4 s=c*0.40;\n s+=(content.eval(clamp(q+float2(r,0.0),lo,hi))+content.eval(clamp(q-float2(r,0.0),lo,hi))+content.eval(clamp(q+float2(0.0,r),lo,hi))+content.eval(clamp(q-float2(0.0,r),lo,hi)))*0.15;\n if(c.a<0.001)return c;\n half4 o=mix(c,s,half(a));\n return half4(clamp(o.rgb*half(1.0-0.95*a),half3(0.0),half3(c.a)),c.a);\n}"; }
